-- 448_hidden_curated.sql — #448 Tampa story batch: 24 HIDDEN storyless OSM pins brought back with a story (drafted 2026-11-01).
-- Same shape and rules as 447_hidden_curated*.sql: exact stored name at the stored coordinate, read from the stored places:v34 rows.
-- Every pin passed #542 by pin id (its containing tile stores it) and is hidden in the live serve (story-sort 2026.11.01b:
-- 448_sort_tampa.tsv, 448_sort_tampa_hmdb.tsv, 448_leads_tampa.tsv). Sources: Rogers Park from its article (TP058 — the park pin
-- itself, whose story is the park's and its golf course's); 13 Tampa Riverwalk Historical Monument Trail busts from the Tampa
-- Riverwalk article's honoree list and each person's own article or Tampa Historical Society marker; nine cemetery, memorial and park
-- markers from HMdb (one Florida state marker, F-42, on Spanish American War Memorial Park); the USF Contemporary Art Museum from its
-- article. The 7 busts that FAIL #542 are seeds in names-448-tampa-2.txt instead. Batch file — run in the Mac session after the seed
-- commit, then curated_category_backfill(true); every row should report dist_m 0.
with v(name, lat, lng, description, source_url, note) as (values
  ($t$Rogers Park$t$, 28.0222412::double precision, -82.4237049::double precision, $t$Set aside by the City of Tampa as a park for Black residents in the segregation era and named in 1951 for businessman and philanthropist G. D. Rogers, this riverside park holds Rogers Park Golf Course, built with volunteers under Willie Black and for years the only course open to Tampa's Black golfers.$t$, $t$https://en.wikipedia.org/wiki/Rogers_Park,_Tampa$t$, $t$#448 hidden-pin row: osm_node358704493, stored in 560_-1648, 560_-1649, 561_-1648, 561_-1649; containing tile 560_-1648 stores it (#542)$t$),
  ($t$Vicente Martinez-Ybor$t$, 27.9430037::double precision, -82.4491547::double precision, $t$This Riverwalk bust honors Vicente Martinez Ybor, the cigar manufacturer who founded Ybor City in 1885 and also started an insurance company, a streetcar line and Tampa's first brewery.$t$, $t$https://en.wikipedia.org/wiki/Vicente_Mart%C3%ADnez_Ybor$t$, $t$#448 hidden-pin row: osm_node10115620372, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Gavino Gutierrez$t$, 27.9428204::double precision, -82.449235::double precision, $t$This Riverwalk bust honors Gavino Gutierrez, the Spanish-born civil engineer and surveyor who brought Vicente Martinez Ybor to Tampa and designed Ybor City.$t$, $t$https://en.wikipedia.org/wiki/Gavino_Gutierrez$t$, $t$#448 hidden-pin row: osm_node10115620394, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Paulina Pedroso$t$, 27.9421568::double precision, -82.4495953::double precision, $t$This Riverwalk bust honors Paulina Pedroso, a leader in the fight for Cuban independence whose Ybor City boarding house sheltered José Martí — he called her his second mother.$t$, $t$https://en.wikipedia.org/wiki/Paulina_Pedroso$t$, $t$#448 hidden-pin row: osm_node10115620329, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Peter Oliphant Knight$t$, 27.940362::double precision, -82.4550335::double precision, $t$This Riverwalk bust honors Peter O. Knight, a Tampa lawyer who led Tampa Electric from 1924 to 1946 and gave his name to Peter O. Knight Airport and the Holland & Knight law firm.$t$, $t$https://en.wikipedia.org/wiki/Peter_O._Knight$t$, $t$#448 hidden-pin row: osm_node10115620362, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Stephen M. Sparkman$t$, 27.9416751::double precision, -82.4505004::double precision, $t$This Riverwalk bust honors Stephen M. Sparkman, the first member of the U.S. House of Representatives from Tampa, who helped win federal support for developing the Port of Tampa.$t$, $t$https://en.wikipedia.org/wiki/Tampa_Riverwalk$t$, $t$#448 hidden-pin row: osm_node10115621827, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Moses White$t$, 27.9422678::double precision, -82.4579608::double precision, $t$This Riverwalk bust honors Moses White, a businessman called the "Mayor of Central Avenue" whose Palm Dinette was Tampa's first sit-down restaurant for people of color.$t$, $t$https://en.wikipedia.org/wiki/Moses_White_(activist)$t$, $t$#448 hidden-pin row: osm_node10115620413, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Meroba Hooker Crane$t$, 27.9411939::double precision, -82.4522637::double precision, $t$This Riverwalk bust honors Meroba Hooker Crane, the businesswoman who ran Tampa's first hotel, the Orange Grove Inn, and worked to preserve Oaklawn Cemetery.$t$, $t$https://en.wikipedia.org/wiki/Tampa_Riverwalk$t$, $t$#448 hidden-pin row: osm_node10115620404, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$James McKay, Senior$t$, 27.9414999::double precision, -82.4579779::double precision, $t$This Riverwalk bust honors James McKay Sr., the Scottish-born sea captain whose shipping line first linked Tampa to the outside world; he opened the cattle trade with Cuba in 1858, was elected mayor in 1859 and ran the Union blockade in the Civil War.$t$, $t$https://www.hmdb.org/m.asp?m=27265$t$, $t$#448 hidden-pin row: osm_node10115621830, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Hugh Campbell Macfarlane$t$, 27.940427::double precision, -82.4552385::double precision, $t$This Riverwalk bust honors Hugh C. Macfarlane, the lawyer who in 1892 turned 200 acres of wilderness into the city of West Tampa, giving land and buildings to cigar makers and donating the 40 acres of Macfarlane Park in 1908.$t$, $t$https://www.hmdb.org/m.asp?m=49593$t$, $t$#448 hidden-pin row: osm_node10115620333, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Francisco Aristides Rodriquez, Junior$t$, 27.9419647::double precision, -82.4581648::double precision, $t$This Riverwalk bust honors Francisco A. Rodriguez Jr., a lawyer who fought for fair treatment of African Americans in Florida's criminal courts and led the local NAACP and La Unión Martí-Maceo.$t$, $t$https://en.wikipedia.org/wiki/Tampa_Riverwalk$t$, $t$#448 hidden-pin row: osm_node10115620348, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Cyril (C.) Blythe Andrews$t$, 27.9412579::double precision, -82.4518236::double precision, $t$This Riverwalk bust honors Cyril Blythe Andrews, a Tampa minister and civil-rights advocate who published the Florida Sentinel Bulletin newspaper.$t$, $t$https://en.wikipedia.org/wiki/Tampa_Riverwalk$t$, $t$#448 hidden-pin row: osm_node10115621818, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Edward Daniel Davis$t$, 27.941604::double precision, -82.4506288::double precision, $t$This Riverwalk bust honors Edward Daniel Davis, a Tampa educator and civil-rights advocate.$t$, $t$https://en.wikipedia.org/wiki/Tampa_Riverwalk$t$, $t$#448 hidden-pin row: osm_node10115620410, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Cody Fowler$t$, 27.9418357::double precision, -82.449809::double precision, $t$This Riverwalk bust honors Cody Fowler, a Tampa lawyer known for defending Black clients when many white lawyers would not; in 1950 he became the first Tampa lawyer to lead the American Bar Association.$t$, $t$https://en.wikipedia.org/wiki/Cody_Fowler$t$, $t$#448 hidden-pin row: osm_node10115620368, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Brandon Family Cemetery$t$, 27.9379184::double precision, -82.2817622::double precision, $t$John Brandon, his wife Martha — a cousin of Kit Carson — and their six sons came by wagon train to Fort Brooke in 1857; he founded the homestead that gave Brandon its name, gave land for its first church and cemetery, and was buried here in 1886.$t$, $t$https://www.hmdb.org/m.asp?m=57356$t$, $t$#448 hidden-pin row: osm_way420153142, stored in 559_-1646; containing tile 559_-1646 stores it (#542)$t$),
  ($t$Port Tampa Cemetery$t$, 27.8681381::double precision, -82.5070244::double precision, $t$Many African American families of Port Tampa buried their dead here in the segregation era; the unregistered cemetery disappeared by the 1930s inside what is now MacDill Air Force Base, until a 1935 WPA graves register found by the Tampa Bay History Center brought it back to light.$t$, $t$https://www.hmdb.org/m.asp?m=214931$t$, $t$#448 hidden-pin row: osm_node11534941192, stored in 557_-1650, 558_-1650; containing tile 557_-1650 stores it (#542)$t$),
  ($t$Memorial Highway$t$, 27.9450028::double precision, -82.5296354::double precision, $t$This monument, moved here from Oldsmar, marked one end of the nation's first "Road of Remembrance" after World War I, dedicated in 1921 to the 105 men and one woman from Hillsborough County who died in service; the Rotary Club of Tampa created the road and paid to beautify it.$t$, $t$https://www.hmdb.org/m.asp?m=101644$t$, $t$#448 hidden-pin row: osm_node10198454352, stored in 559_-1650, 559_-1651; containing tile 559_-1651 stores it (#542)$t$),
  ($t$War Correspondents Memorial$t$, 28.035597::double precision, -82.3867459::double precision, $t$Dedicated on May 1, 1982 by the Temple Terrace Beacon newspaper, this flag memorial honors the war correspondents — armed only with camera and typewriter — who gave their lives sending news of America's battles home.$t$, $t$https://www.hmdb.org/m.asp?m=214938$t$, $t$#448 hidden-pin row: osm_node9338193244, stored in 560_-1648, 561_-1647, 561_-1648; containing tile 561_-1648 stores it (#542)$t$),
  ($t$Pam Callahan Nature Preserve Marker$t$, 27.9778148::double precision, -82.5684391::double precision, $t$Pam Callahan led a nearly three-year community fight that stopped a developer from building on these wetlands, leaving the land to be bought for public protection; she died before it opened, and it carries her name.$t$, $t$https://www.hmdb.org/m.asp?m=13647$t$, $t$#448 hidden-pin row: osm_node5058235265, stored in 559_-1651, 560_-1651, 560_-1652; containing tile 560_-1651 stores it (#542)$t$),
  ($t$University Of South Florida Contemporary Art Museum;Contemporary Art Museum$t$, 28.0634958::double precision, -82.4155503::double precision, $t$Opened here beside the USF College of the Arts in 1989, the university's accredited Contemporary Art Museum looks after USF's permanent collection of more than 5,000 works of art.$t$, $t$https://en.wikipedia.org/wiki/University_of_South_Florida_Contemporary_Art_Museum$t$, $t$#448 hidden-pin row: osm_way43097398, stored in 561_-1648, 561_-1649; containing tile 561_-1648 stores it (#542)$t$),
  ($t$A.J. Palonis Jr. Park$t$, 27.8921306::double precision, -82.5408434::double precision, $t$This park honors Lt. Col. Anthony J. Palonis Jr., a Marine who served in World War II, Korea and Vietnam — with Edson's Raiders at Bloody Ridge on Guadalcanal — and was awarded the Silver Star, the Bronze Star for Valor and two Purple Hearts.$t$, $t$https://www.hmdb.org/m.asp?m=55280$t$, $t$#448 hidden-pin row: osm_way211019250, stored in 558_-1650, 558_-1651; containing tile 558_-1651 stores it (#542)$t$),
  ($t$Rough Riders Park$t$, 27.9600833::double precision, -82.4460574::double precision, $t$Dedicated on March 1, 2003, this Ybor City park honors Theodore Roosevelt and the 1st U.S. Volunteer Cavalry, the Rough Riders, who gathered in Tampa in 1898 when the city was the army's assembly and embarkation point for the war in Cuba.$t$, $t$https://www.hmdb.org/m.asp?m=32795$t$, $t$#448 hidden-pin row: osm_way28093787, stored in 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Centennial Park$t$, 27.9613418::double precision, -82.438607::double precision, $t$The city council named this Ybor Centennial Park in 1986 for Ybor City's hundredth year, and it honors Vicente Martinez-Ybor, the developer of the cigar town.$t$, $t$https://www.hmdb.org/m.asp?m=8750$t$, $t$#448 hidden-pin row: osm_way26216272, stored in 559_-1648, 559_-1649; containing tile 559_-1649 stores it (#542)$t$),
  ($t$Spanish American War Memorial Park$t$, 27.8666545::double precision, -82.5265443::double precision, $t$From April to June 1898 Tampa was the army's port of embarkation for the war in Cuba: some 30,000 troops arrived, and 16,000 sailed from Port Tampa on June 7.$t$, $t$https://www.hmdb.org/m.asp?m=13635$t$, $t$#448 hidden-pin row: osm_way469618168, stored in 557_-1650, 557_-1651; containing tile 557_-1651 stores it (#542)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
